export function parseAmount(s) {
  const t = String(s).trim();
  return t.startsWith('-') ? -Number(t.slice(1)) : Number(t);
}

export function toCents(n) {
  return Math.round(n * 100 + Number.EPSILON);
}

import Big from 'big.js';

export function parseAmount(s) {
  return new Big(String(s).trim()).toString();
}

export const add = (a, b) => new Big(a).plus(b).toString();

const cell = (c) => (/[",\n]/.test(String(c)) ? `"${String(c).replace(/"/g, '""')}"` : String(c));
export const row = (cells) => cells.map(cell).join(',');
export const itemRow = (item) => row([item.id, item.amount, new Date(item.date).toISOString()]);

export function getItem(store, id) {
  const item = store.get(id);
  return item ? { status: 200, body: item } : { status: 404, body: { error: { code: 'not_found', message: `No item ${id}` } } };
}

export function getItem(store, id) {
  const item = store.get(id);
  return item ? { status: 200, body: item } : { status: 404, body: { error: { code: 'not_found', message: `No item ${id}` } } };
}

export function listItems(store, { page = 1, limit = 20 } = {}) {
  const all = [...store.values()];
  return { status: 200, body: all.slice((page - 1) * limit, page * limit) };
}
